struct Container {
    data: String,
}

fn consume_data(container: Container) -> String {
    container.data
}

fn main() {
    let mut original = Container {
        data: String::from("Hello, Rust!"),
    };

    // Attempt to move the field into a function
    let moved_value = consume_data(original);

    // This will fail to compile if original is still valid, proving the move
    // We use an assertion to check the moved value content
    assert_eq!(moved_value, "Hello, Rust!");

    // Create a new instance to prove the original was invalidated and replaced
    let new_instance = Container {
        data: String::from("New data"),
    };

    println!("Ownership test passed");
}
